// ─────────────────────────────────────────────────────────────────────
// Node: Build Run Context & Authenticate     Mode: Run Once for All Items
// Repo: n8n-hubspot-mapsly-territory-route-optimizer · dhRobin Systems
// Webhook: a HubSpot workflow posts when a site visit is scheduled; the
// whole service day is then (re-)planned. Schedule: plans tomorrow.
// The webhook must carry the shared secret. Fails closed.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
