    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);
const PLAN_TZ = (() => { const tz = env('PLANNING_TIMEZONE', 'UTC'); try { new Intl.DateTimeFormat('en-US', { timeZone: tz }); return tz; } catch (e) { return 'UTC'; } })();
const tzOffsetMs = (utcMs, tz) => {
  const parts = new Intl.DateTimeFormat('en-US', { timeZone: tz, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' })
    .formatToParts(new Date(utcMs)).filter((p) => p.type !== 'literal');
  const p = Object.fromEntries(parts.map((x) => [x.type, Number(x.value)]));
  return Date.UTC(p.year, p.month - 1, p.day, p.hour % 24, p.minute, p.second) - utcMs;
};
// Local wall-clock time on a date (YYYY-MM-DD) in PLAN_TZ → UTC epoch ms
const localToUtc = (dateStr, minutesFromMidnight) => {
  const [y, m, d] = dateStr.split('-').map(Number);
  const guess = Date.UTC(y, m - 1, d, 0, 0) + minutesFromMidnight * 60000;
  const off1 = tzOffsetMs(guess, PLAN_TZ);
  let utc = guess - off1;
  const off2 = tzOffsetMs(utc, PLAN_TZ);
  if (off2 !== off1) utc = guess - off2;
  return utc;
};
const localDate = (utcMs) => new Intl.DateTimeFormat('en-CA', { timeZone: PLAN_TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(utcMs));
const hhmmToMin = (v, fallback) => {
  const m = String(v ?? '').trim().match(/^(\d{1,2}):(\d{2})$/);
  if (!m) return fallback;
  const n = Number(m[1]) * 60 + Number(m[2]);
  return n >= 0 && n <= 24 * 60 ? n : fallback;
};
const minToHhmm = (min) => { const r = Math.round(min); return `${String(Math.floor(r / 60)).padStart(2, '0')}:${String(r % 60).padStart(2, '0')}`; };

let crypto = null;
try { crypto = require('crypto'); } catch (error) { crypto = null; }

const SANDBOX_MODE = flag('SANDBOX_MODE', true);
const DRY_RUN = flag('DRY_RUN', true);
const SECRET_HEADER = env('WEBHOOK_SECRET_HEADER', 'x-webhook-secret').toLowerCase();
const SANDBOX_FIXTURE_SECRET = 'sandbox-fictional-secret-not-for-production';
const EXPECTED_SECRET = env('WEBHOOK_SHARED_SECRET', '') || (SANDBOX_MODE ? SANDBOX_FIXTURE_SECRET : '');
const MAX_DAYS_AHEAD = Math.max(1, num('MAX_PLAN_DAYS_AHEAD', 30));

const safeEqual = (a, b) => {
  if (typeof a !== 'string' || typeof b !== 'string' || !a || !b) return false;
  if (crypto) return crypto.timingSafeEqual(crypto.createHash('sha256').update(a).digest(), crypto.createHash('sha256').update(b).digest());
  let diff = a.length ^ b.length;
  for (let i = 0; i < Math.max(a.length, b.length); i++) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return diff === 0;
};

let runId;
try { runId = 'route_' + crypto.randomUUID(); } catch (error) { runId = 'route_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 10); }

const input = $input.first() ? $input.first().json : {};
const isWebhook = !!(input && input.headers && typeof input.headers === 'object');
const nowMs = Date.now();
const today = localDate(nowMs);

const toPlanDate = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const s = String(v).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  if (/^\d{10,13}$/.test(s)) return new Date(Number(s.length === 10 ? Number(s) * 1000 : s)).toISOString().slice(0, 10); // HubSpot date = midnight UTC
  const t = Date.parse(s);
  return Number.isFinite(t) ? new Date(t).toISOString().slice(0, 10) : null;
};

const run = {
  runId,
  startedAt: new Date(nowMs).toISOString(),
  mode: SANDBOX_MODE ? 'sandbox' : DRY_RUN ? 'dry_run' : 'live',
  sandboxMode: SANDBOX_MODE,
  dryRun: DRY_RUN,
  trigger: isWebhook ? 'webhook' : 'schedule',
  timezone: PLAN_TZ,
  hubspotApiBase: env('HUBSPOT_API_BASE_URL', 'https://api.hubapi.com'),
  accepted: true,
  rejectReason: null,
  planDate: null,
  triggerRecord: null,
};

const fixtures = SANDBOX_MODE && input && typeof input.sandboxFixtures === 'object' ? input.sandboxFixtures : null;

if (isWebhook) {
  const headers = {};
  for (const [k, v] of Object.entries(input.headers || {})) headers[String(k).toLowerCase()] = Array.isArray(v) ? String(v[0]) : String(v);
  if (!EXPECTED_SECRET) { run.accepted = false; run.rejectReason = 'shared_secret_not_configured'; }
  else if (!safeEqual(headers[SECRET_HEADER] || '', EXPECTED_SECRET)) { run.accepted = false; run.rejectReason = 'shared_secret_mismatch'; }
  else {
    let body = input.body;
    if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
    body = body && typeof body === 'object' ? body : {};
    const props = body.properties && typeof body.properties === 'object' ? body.properties : body;
    const val = (k) => (props[k] && typeof props[k] === 'object' && 'value' in props[k] ? props[k].value : props[k]);
    run.triggerRecord = {
      objectType: String(body.objectType || '').toLowerCase().includes('ticket') ? 'ticket' : 'deal',
      objectId: body.objectId != null ? String(body.objectId) : body.hs_object_id != null ? String(body.hs_object_id) : null,
    };
    run.planDate = body.planDate === 'SANDBOX_TOMORROW' && SANDBOX_MODE ? localDate(nowMs + 86400000) : toPlanDate(body.planDate) || toPlanDate(val('site_visit_date'));
    if (!run.planDate) { run.accepted = false; run.rejectReason = 'plan_date_missing'; }
  }
} else {
  run.planDate = localDate(nowMs + 86400000);
}

if (run.accepted) {
  const daysAhead = Math.round((Date.parse(run.planDate + 'T00:00:00Z') - Date.parse(today + 'T00:00:00Z')) / 86400000);
  if (daysAhead < 0) { run.accepted = false; run.rejectReason = 'plan_date_in_past'; }
  else if (daysAhead > MAX_DAYS_AHEAD) { run.accepted = false; run.rejectReason = 'plan_date_too_far_ahead'; }
}

return [{ json: { kind: run.accepted ? 'run' : 'rejected', run, sandboxFixtures: fixtures } }];

// ─────────────────────────────────────────────────────────────────────
// Node: Load Sandbox Visits                  Mode: Run Once for All Items
// Emits fictional HubSpot deal/ticket records and a fictional technician
// roster in the same shape as the live "Collect HubSpot Visits" node.
// ─────────────────────────────────────────────────────────────────────
const { run, sandboxFixtures } = $input.first().json;
if (!sandboxFixtures) {
  return [{ json: { kind: 'raw', run, records: [], roster: [], source: 'sandbox_fixtures_missing', fetchErrors: ['sandbox fixtures missing: execute the pinned trigger'] } }];
}
return [{
  json: {
    kind: 'raw',
    run,
    source: 'sandbox_fixtures',
    records: sandboxFixtures.visits || [],
    roster: sandboxFixtures.technicians || [],
    fetchErrors: [],
    sandboxGeo: sandboxFixtures.geocodes || {},
    sandboxPriorDispatch: sandboxFixtures.priorDispatch || [],
  },
}];

// ─────────────────────────────────────────────────────────────────────
// Node: Collect HubSpot Visits               Mode: Run Once for All Items
// Merges the paginated deal and ticket searches for the plan date and
// reads the technician roster from TECHNICIAN_ROSTER_JSON.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const run = $('Build Run Context & Authenticate').first().json.run;
const fetchErrors = [];
const records = [];
const clean = (s) => String(s || '').replace(/Bearer\s+[A-Za-z0-9\-._~+\/]+=*/gi, 'Bearer [REDACTED]').slice(0, 200);

const absorb = (pages, objectType) => {
  for (const p of pages) {
    const body = p.json || {};
    if (body.error) { fetchErrors.push(`${objectType}s: ${clean(body.error.message || body.error)}`); continue; }
    if (body.status === 'error') { fetchErrors.push(`${objectType}s: ${clean(body.category || body.message)}`); continue; }
    for (const r of body.results || []) records.push({ objectType, id: String(r.id), properties: r.properties || {} });
  }
};
absorb($('Search Scheduled Deals').all(), 'deal');
if (flag('INCLUDE_TICKETS', true)) absorb($input.all(), 'ticket');

let roster = [];
try {
  const parsed = JSON.parse(env('TECHNICIAN_ROSTER_JSON', '[]'));
  roster = Array.isArray(parsed) ? parsed : [];
} catch (error) {
  fetchErrors.push('TECHNICIAN_ROSTER_JSON is not valid JSON');
}

return [{ json: { kind: 'raw', run, source: 'hubspot_api', records, roster, fetchErrors } }];

// ─────────────────────────────────────────────────────────────────────
// Node: Normalize Visits & Roster            Mode: Run Once for All Items
// Turns HubSpot records into stops and the roster into technicians.
// Records that can't be planned (missing address, cancelled) are kept as
// pre-unassigned stops with a reason, so nothing disappears silently.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
