  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);
const PLAN_TZ = (() => { const tz = env('PLANNING_TIMEZONE', 'UTC'); try { new Intl.DateTimeFormat('en-US', { timeZone: tz }); return tz; } catch (e) { return 'UTC'; } })();
const tzOffsetMs = (utcMs, tz) => {
  const parts = new Intl.DateTimeFormat('en-US', { timeZone: tz, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' })
    .formatToParts(new Date(utcMs)).filter((p) => p.type !== 'literal');
  const p = Object.fromEntries(parts.map((x) => [x.type, Number(x.value)]));
  return Date.UTC(p.year, p.month - 1, p.day, p.hour % 24, p.minute, p.second) - utcMs;
};
// Local wall-clock time on a date (YYYY-MM-DD) in PLAN_TZ → UTC epoch ms
const localToUtc = (dateStr, minutesFromMidnight) => {
  const [y, m, d] = dateStr.split('-').map(Number);
  const guess = Date.UTC(y, m - 1, d, 0, 0) + minutesFromMidnight * 60000;
  const off1 = tzOffsetMs(guess, PLAN_TZ);
  let utc = guess - off1;
  const off2 = tzOffsetMs(utc, PLAN_TZ);
  if (off2 !== off1) utc = guess - off2;
  return utc;
};
const localDate = (utcMs) => new Intl.DateTimeFormat('en-CA', { timeZone: PLAN_TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(utcMs));
const hhmmToMin = (v, fallback) => {
  const m = String(v ?? '').trim().match(/^(\d{1,2}):(\d{2})$/);
  if (!m) return fallback;
  const n = Number(m[1]) * 60 + Number(m[2]);
  return n >= 0 && n <= 24 * 60 ? n : fallback;
};
const minToHhmm = (min) => { const r = Math.round(min); return `${String(Math.floor(r / 60)).padStart(2, '0')}:${String(r % 60).padStart(2, '0')}`; };

const src = $input.first().json;
const run = src.run;
const DEFAULT_DURATION = Math.max(5, num('DEFAULT_VISIT_MINUTES', 60));
const DEFAULT_WIN_START = hhmmToMin(env('DEFAULT_WINDOW_START', '08:00'), 480);
const DEFAULT_WIN_END = hhmmToMin(env('DEFAULT_WINDOW_END', '17:00'), 1020);
const MAX_STOPS = Math.max(1, num('MAX_STOPS_PER_RUN', 200));
const PLANNABLE = new Set(['scheduled', 'confirmed', '']);

const list = (v) => String(v ?? '').split(/[;,]/).map((s) => s.trim().toLowerCase()).filter(Boolean);
const numOrNull = (v) => (v === null || v === undefined || v === '' || !Number.isFinite(Number(v)) ? null : Number(v));

const stops = [];
const preUnassigned = [];
for (const r of (src.records || []).slice(0, MAX_STOPS)) {
  const p = r.properties || {};
  const status = String(p.site_visit_status || '').toLowerCase();
  const address = [p.site_visit_street, p.site_visit_city, p.site_visit_state, p.site_visit_postal_code, p.site_visit_country].filter((x) => x && String(x).trim()).join(', ');
  const lat = numOrNull(p.site_visit_latitude);
  const lng = numOrNull(p.site_visit_longitude);
  let winStart = hhmmToMin(p.site_visit_window_start, DEFAULT_WIN_START);
  let winEnd = hhmmToMin(p.site_visit_window_end, DEFAULT_WIN_END);
  if (winEnd <= winStart) { winStart = DEFAULT_WIN_START; winEnd = DEFAULT_WIN_END; }
  const stop = {
    stopId: `${r.objectType}:${r.id}`,
    objectType: r.objectType,
    recordId: r.id,
    label: String((r.objectType === 'deal' ? p.dealname : p.subject) || `${r.objectType} ${r.id}`).slice(0, 120),
    address,
    city: p.site_visit_city || null,
    lat: lat !== null && lng !== null ? lat : null,
    lng: lat !== null && lng !== null ? lng : null,
    preGeocoded: lat !== null && lng !== null,
    skills: list(p.site_visit_required_skills),
    durationMin: Math.max(5, numOrNull(p.site_visit_duration_minutes) ?? DEFAULT_DURATION),
    windowStartMin: winStart,
    windowEndMin: winEnd,
    priority: ['high', 'normal', 'low'].includes(String(p.site_visit_priority || '').toLowerCase()) ? String(p.site_visit_priority).toLowerCase() : 'normal',
    isTriggerRecord: !!(run.triggerRecord && run.triggerRecord.objectId === r.id),
  };
  if (!PLANNABLE.has(status)) { preUnassigned.push({ ...stop, reason: 'status_not_plannable', detail: status }); continue; }
  if (!address && !stop.preGeocoded) { preUnassigned.push({ ...stop, reason: 'address_missing', detail: 'site_visit_street/city/postal code are empty' }); continue; }
  stops.push(stop);
}

const techs = [];
const rosterIssues = [];
for (const t of src.roster || []) {
  if (!t || t.active === false) continue;
  const start = t.start || {};
  if (!t.id || !Number.isFinite(Number(start.lat)) || !Number.isFinite(Number(start.lng))) { rosterIssues.push(`technician ${t && t.id ? t.id : '?'} skipped: id and start.lat/lng are required`); continue; }
  const end = t.end && Number.isFinite(Number(t.end.lat)) ? t.end : start;
  const shiftStartMin = hhmmToMin(t.shiftStart, 480);
  const shiftEndMin = hhmmToMin(t.shiftEnd, 1020);
  if (shiftEndMin <= shiftStartMin) { rosterIssues.push(`technician ${t.id} skipped: shiftEnd must be after shiftStart`); continue; }
  techs.push({
