    end: { lat: Number(end.lat), lng: Number(end.lng), label: end.label || start.label || 'End' },
    shiftStartMin,
    shiftEndMin,
    maxStops: Math.max(1, Number(t.maxStops) || 8),
    connecteamUserId: t.connecteamUserId != null && t.connecteamUserId !== '' ? Number(t.connecteamUserId) : null,
