      preUnassigned, rosterIssues, fetchErrors: src.fetchErrors || [], visitCount: (src.records || []).length,
    },
  }];
}

return [{
  json: {
    kind: 'plan_input',
    run,
    stops,
    techs,
    preUnassigned,
    rosterIssues,
    fetchErrors: src.fetchErrors || [],
    sandboxGeo: src.sandboxGeo,
    sandboxPriorDispatch: src.sandboxPriorDispatch,
    geocodeRequest: {
      requestId: run.runId,
      planDate: run.planDate,
      stops: stops.map((s) => (s.preGeocoded ? { stopId: s.stopId, lat: s.lat, lng: s.lng } : { stopId: s.stopId, address: s.address })),
    },
  },
}];

// ─────────────────────────────────────────────────────────────────────
// Node: Simulate Mapsly Geocode & Territory  Mode: Run Once for All Items
// Sandbox stand-in for the Mapsly custom API endpoint. Answers in the
// same envelope a Mapsly sync endpoint uses: { code, data }.
// ─────────────────────────────────────────────────────────────────────
const plan = $input.first().json;
const table = plan.sandboxGeo || {};
const results = plan.geocodeRequest.stops.map((s) => {
  const hit = table[s.stopId];
  if (!hit) return { stopId: s.stopId, matchQuality: 'none', lat: null, lng: null, territories: [] };
  return { stopId: s.stopId, lat: s.lat ?? hit.lat, lng: s.lng ?? hit.lng, matchQuality: s.lat != null ? 'provided' : hit.matchQuality || 'street', formattedAddress: hit.formattedAddress || null, territories: hit.territories || [] };
});
return [{ json: { statusCode: 200, body: { code: 200, data: { requestId: plan.geocodeRequest.requestId, results } } } }];

// ─────────────────────────────────────────────────────────────────────
// Node: Cluster Stops by Proximity           Mode: Run Once for All Items
// 1. Merges Mapsly geocodes + territories into the stops (quality gate).
// 2. Clusters stops: first by primary territory, then greedily by radius.
// 3. Builds sparse travel-time pair requests for the Mapsly matrix
//    endpoint (k nearest neighbours + technician start/end legs), batched.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
