  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);
const haversineKm = (a, b) => {
  const R = 6371, toRad = (d) => (d * Math.PI) / 180;
  const dLat = toRad(b.lat - a.lat), dLng = toRad(b.lng - a.lng);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.min(1, Math.sqrt(h)));
};
// Straight-line → road estimate: detour factor plus a distance-banded average speed.
const ROAD_FACTOR = Math.max(1, num('FALLBACK_ROAD_FACTOR', 1.35));
const estimateLeg = (a, b) => {
  const km = haversineKm(a, b) * ROAD_FACTOR;
  const kmh = km < 5 ? num('FALLBACK_SPEED_URBAN_KMH', 30) : km < 25 ? num('FALLBACK_SPEED_SUBURBAN_KMH', 45) : num('FALLBACK_SPEED_HIGHWAY_KMH', 70);
  return { durationSec: Math.round((km / Math.max(5, kmh)) * 3600), distanceMeters: Math.round(km * 1000) };
};

const ctx = $('Visits to Plan?').first().json;
const resp = $input.first() ? $input.first().json : {};
const MIN_QUALITY = env('MIN_GEOCODE_QUALITY', 'street').toLowerCase();
const QUALITY = { provided: 5, rooftop: 4, street: 3, postal: 2, city: 1, none: 0 };
const RADIUS_KM = Math.max(0.5, num('CLUSTER_RADIUS_KM', 15));
const NEIGHBOURS = Math.max(2, num('MATRIX_NEIGHBORS', 8));
const PAIRS_PER_CALL = Math.max(10, num('MAPSLY_MAX_PAIRS_PER_CALL', 300));

// ── 1 · Geocode merge ─────────────────────────────────────────────────
const statusCode = Number(resp.statusCode || 0);
const envelope = resp.body || {};
const payloadCode = Number(envelope.code || statusCode || 0);
const data = envelope.data || envelope;
const geoOk = statusCode === 200 && payloadCode < 400 && Array.isArray(data.results);
const byId = {};
if (geoOk) for (const r of data.results) if (r && r.stopId) byId[String(r.stopId)] = r;

const stops = [];
const unassigned = [...(ctx.preUnassigned || [])];
for (const s of ctx.stops) {
  const g = byId[s.stopId];
  const territories = g && Array.isArray(g.territories) ? g.territories.map((t) => ({ id: String(t.id ?? t).toLowerCase(), name: t.name || String(t.id ?? t) })) : [];
  if (s.preGeocoded) { stops.push({ ...s, territories, geocodeQuality: 'provided' }); continue; }
