return $input.all().map(({ json }) => {
  const pts = Object.fromEntries(json.request.points.map((p) => [p.id, p]));
  const legs = json.request.pairs.map(([from, to]) => ({ from, to, ...estimateLeg(pts[from], pts[to]) }));
  return { json: { statusCode: 200, body: { code: 200, data: { requestId: json.request.requestId, legs, source: 'sandbox_simulated' } } } };
});

// ─────────────────────────────────────────────────────────────────────
// Node: Route & Schedule Optimization Engine Mode: Run Once for All Items
// Inputs: clustered stops + technicians (from Cluster Stops by Proximity)
//         and the Mapsly travel-time legs (one item per matrix batch).
// Steps:  1 eligibility (skills, territory)   2 priority-ordered cheapest
