};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);
const haversineKm = (a, b) => {
  const R = 6371, toRad = (d) => (d * Math.PI) / 180;
  const dLat = toRad(b.lat - a.lat), dLng = toRad(b.lng - a.lng);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.min(1, Math.sqrt(h)));
};
// Straight-line → road estimate: detour factor plus a distance-banded average speed.
const ROAD_FACTOR = Math.max(1, num('FALLBACK_ROAD_FACTOR', 1.35));
const estimateLeg = (a, b) => {
  const km = haversineKm(a, b) * ROAD_FACTOR;
