// ── Travel-time lookup (Mapsly legs, else estimate) ───────────────────
const legs = {};
let legsReturned = 0;
let matrixFailures = 0;
for (const { json } of $input.all()) {
  const ok = Number(json.statusCode) === 200 && json.body && Number(json.body.code || 200) < 400;
  const data = json.body ? json.body.data || json.body : {};
  if (!ok || !Array.isArray(data.legs)) { matrixFailures++; continue; }
