// ── 2 · Cheapest insertion (priority first, tightest windows first) ───
const routes = Object.fromEntries(plan.techs.map((t) => [t.techId, []]));
const evals = Object.fromEntries(plan.techs.map((t) => [t.techId, evaluate(t, [])]));
const techById = Object.fromEntries(plan.techs.map((t) => [t.techId, t]));
const unassigned = [...plan.unassigned];
