        stops: seq.length, driveMin: Math.round(ev.drive), distanceKm: r1(ev.dist / 1000), serviceMin, waitMin: Math.round(ev.wait),
        departAt: minToHhmm(tech.shiftStartMin), finishAt: seq.length ? minToHhmm(ev.finishMin) : null,
        utilisationPct: seq.length ? Math.round(((serviceMin + ev.drive) / shiftLen) * 100) : 0,
        baselineDriveMin: Math.round(base), savingsPct: base > 0 ? Math.max(0, Math.round(((base - ev.drive) / base) * 100)) : 0,
      },
      fingerprint,
      dispatchAction,
      priorShiftIds: prior ? prior.shiftIds || [] : [],
    },
  });
}

// ── Plan summary & alerts ─────────────────────────────────────────────
const assignedCount = routeItems.reduce((a, r) => a + r.json.stops.length, 0);
const allStops = routeItems.flatMap((r) => r.json.stops.map((s) => ({ ...s, techName: r.json.tech.name })));
const alerts = [];
const push = (severity, code, message) => alerts.push({ severity, code, message });
for (const e of plan.fetchErrors) push('critical', 'hubspot_fetch_failed', e);
if (!plan.geocode.ok) push('critical', 'geocode_service_unavailable', `Mapsly geocode endpoint returned ${plan.geocode.statusCode || 'network error'}`);
if (matrixFailures) push('warning', 'matrix_batches_failed', `${matrixFailures} of ${plan.matrix.batches} travel-time batches failed; estimates used`);
if (estimatedKeys.size && !SANDBOX_MODE) push('warning', 'estimated_travel_times', `${estimatedKeys.size} legs used straight-line estimates`);
const highUnassigned = unassigned.filter((u) => u.priority === 'high');
if (highUnassigned.length) push('critical', 'high_priority_unassigned', `${highUnassigned.length} high-priority visit(s) could not be scheduled`);
if (unassigned.length) push('warning', 'visits_unassigned', `${unassigned.length} visit(s) unassigned`);
const late = allStops.filter((s) => s.lateRisk);
if (late.length) push('warning', 'late_risk', `${late.length} stop(s) start within ${LATE_RISK_SLACK} min of the window end`);
const mismatch = allStops.filter((s) => s.territoryMismatch);
if (mismatch.length) push('info', 'territory_mismatch', `${mismatch.length} stop(s) served outside the technician's territory`);
const changed = routeItems.filter((r) => r.json.dispatchAction === 'changed_after_dispatch');
if (changed.length) push('warning', 'route_changed_after_dispatch', `${changed.map((r) => r.json.tech.name).join(', ')}: route changed after shifts were dispatched; update Connecteam manually`);
for (const r of plan.rosterIssues) push('warning', 'roster_issue', r);

const severity = alerts.some((a) => a.severity === 'critical') ? 'critical' : alerts.some((a) => a.severity === 'warning') ? 'warning' : 'ok';
const totalDrive = routeItems.reduce((a, r) => a + r.json.totals.driveMin, 0);
const totalBase = routeItems.reduce((a, r) => a + r.json.totals.baselineDriveMin, 0);

const summary = {
  kind: 'plan_summary', run, planDate: run.planDate, severity,
  totals: {
    visits: plan.stops.length + plan.unassigned.length, plannable: plan.stops.length, assigned: assignedCount, unassigned: unassigned.length,
    techniciansUsed: routeItems.filter((r) => r.json.stops.length).length, techniciansAvailable: plan.techs.length,
    driveMin: totalDrive, distanceKm: r1(routeItems.reduce((a, r) => a + r.json.totals.distanceKm, 0)),
    baselineDriveMin: totalBase, savingsPct: totalBase > 0 ? Math.max(0, Math.round(((totalBase - totalDrive) / totalBase) * 100)) : 0,
  },
  routes: routeItems.map((r) => ({ techId: r.json.tech.techId, name: r.json.tech.name, stops: r.json.stops.length, driveMin: r.json.totals.driveMin, finishAt: r.json.totals.finishAt, dispatchAction: r.json.dispatchAction })),
  unassigned: unassigned.map((u) => ({ stopId: u.stopId, objectType: u.objectType, recordId: u.recordId, label: u.label, city: u.city || null, priority: u.priority, reason: u.reason, detail: u.detail || null })),
  alerts,
  clusters: plan.clusters.map((c) => ({ clusterId: c.clusterId, territory: c.territory, size: c.size })),
  geocode: plan.geocode,
  matrix: { ...plan.matrix, legsReturned, matrixFailures, estimatedLegsUsed: estimatedKeys.size },
  optimizer: { territoryMode: TERRITORY_MODE, twoOptMoves, relocateMoves },
};

return [...routeItems, { json: summary }];

// ─────────────────────────────────────────────────────────────────────
// Node: Build Dispatch Payloads              Mode: Run Once for All Items
// Field Dispatch & Notification Router:
//   • one Connecteam shift batch per technician route (one shift per stop,
//     with address/GPS and route notes), only for routes not yet dispatched
//   • one Slack Block Kit plan summary + operational alerts for dispatchers
// Every item gets `route`: connecteam_live | slack_live | simulate
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
