const SANDBOX_MODE = flag('SANDBOX_MODE', true);
const DRY_RUN = flag('DRY_RUN', true);
const LIVE = !SANDBOX_MODE && !DRY_RUN;
const CONNECTEAM_ENABLED = flag('CONNECTEAM_ENABLED', true);
const SLACK_ENABLED = flag('SLACK_ENABLED', true);
const PUBLISH = flag('CONNECTEAM_PUBLISH_SHIFTS', false); // drafts by default: a dispatcher reviews first
