const JOB_ID = env('CONNECTEAM_JOB_ID', '');
const INCLUDE_LINK = flag('CONNECTEAM_INCLUDE_HUBSPOT_LINK', false);
const NOTIFY_ON_EMPTY = flag('NOTIFY_ON_EMPTY_PLAN', false);
const PORTAL = env('HUBSPOT_PORTAL_ID', 'YOUR_HUBSPOT_PORTAL_ID');
const APP = env('HUBSPOT_APP_BASE_URL', 'https://app.hubspot.com').replace(/\/+$/, '');
const MENTION = env('SLACK_MENTION_ON_CRITICAL', '');

const items = $input.all().map((i) => i.json);
const html = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const recordLink = (objectType, id) => `${APP}/contacts/${encodeURIComponent(PORTAL)}/record/${objectType === 'ticket' ? '0-5' : '0-3'}/${encodeURIComponent(id)}`;
const REASON = {
  no_tech_with_required_skills: 'no technician has the required skills',
  no_tech_in_territory: 'no technician covers this territory',
  no_feasible_time_slot: 'no slot fits the time window and shift hours',
  geocode_low_quality: 'address could not be geocoded precisely',
  geocode_service_unavailable: 'geocoding service unavailable',
  address_missing: 'address missing',
  status_not_plannable: 'visit status is not schedulable',
};

const connecteamDelivery = !CONNECTEAM_ENABLED ? 'disabled' : !LIVE ? 'dry_run' : env('CONNECTEAM_API_TOKEN', '') && SCHEDULER_ID ? 'live' : 'not_configured';
const slackDelivery = !SLACK_ENABLED ? 'disabled' : !LIVE ? 'dry_run' : env('SLACK_WEBHOOK_URL', '') ? 'live' : 'not_configured';

const out = [];

// ── Nothing to plan ───────────────────────────────────────────────────
const empty = items.find((i) => i.kind === 'nothing_to_plan');
if (empty) {
  const problems = [...(empty.fetchErrors || []), ...(empty.rosterIssues || [])];
  const alert = problems.length > 0 || empty.reason === 'no_active_technicians';
  if (alert || NOTIFY_ON_EMPTY) {
    const blocks = [
      { type: 'header', text: { type: 'plain_text', text: `${alert ? '🟠' : '⚪'} Route plan · ${empty.run.planDate} · nothing planned`, emoji: true } },
      { type: 'section', text: { type: 'mrkdwn', text: `*Reason:* ${esc(empty.reason.replace(/_/g, ' '))} · ${empty.visitCount} visit record(s) found${(empty.preUnassigned || []).length ? `, ${empty.preUnassigned.length} not plannable` : ''}` } },
    ];
    if (problems.length) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*Problems*\n${problems.slice(0, 10).map((p) => `• ${esc(p)}`).join('\n')}` } });
    blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `Run \`${esc(empty.run.runId)}\` · mode ${esc(empty.run.mode)}` }] });
    out.push({ json: { kind: 'slack_summary', run: empty.run, planDate: empty.run.planDate, severity: alert ? 'warning' : 'ok', delivery: slackDelivery, route: slackDelivery === 'live' ? 'slack_live' : 'simulate', slackMessage: { text: `Route plan ${empty.run.planDate}: nothing planned (${empty.reason})`, blocks } } });
  } else {
    out.push({ json: { kind: 'plan_skipped', run: empty.run, planDate: empty.run.planDate, reason: empty.reason, route: 'simulate', delivery: 'none' } });
  }
  return out;
}

const summary = items.find((i) => i.kind === 'plan_summary');
const routes = items.filter((i) => i.kind === 'route');
const run = summary.run;

// ── Connecteam shift batches ──────────────────────────────────────────
for (const r of routes) {
  const base = { run, planDate: r.planDate, tech: { techId: r.tech.techId, name: r.tech.name, connecteamUserId: r.tech.connecteamUserId }, totals: r.totals, fingerprint: r.fingerprint, dispatchAction: r.dispatchAction };
  if (r.dispatchAction !== 'create') { out.push({ json: { kind: 'route_audit', ...base, route: 'simulate', delivery: 'none' } }); continue; }
  const n = r.stops.length;
  const shifts = r.stops.map((s) => {
    const notes = [
      `<p><b>Stop ${s.seq} of ${n}</b> · arrival window ${html(s.window)} · ETA ${html(s.eta)}</p>`,
      `<p>Drive ${html(s.driveMinFromPrev)} min (${html(s.distanceKmFromPrev)} km) from the ${s.seq === 1 ? 'start location' : 'previous stop'}${s.waitMin > 0 ? ` · ${html(s.waitMin)} min wait before the window opens` : ''}</p>`,
      `<p>HubSpot ${html(s.objectType)} ${html(s.recordId)}${s.skills.length ? ` · skills: ${html(s.skills.join(', '))}` : ''}${s.priority === 'high' ? ' · <b>HIGH PRIORITY</b>' : ''}</p>`,
    ];
    if (INCLUDE_LINK) notes.push(`<p><a href="${html(recordLink(s.objectType, s.recordId))}">Open in HubSpot</a></p>`);
    const shift = {
      startTime: Math.floor(localToUtc(r.planDate, Math.round(s.startMin)) / 1000),
      endTime: Math.floor(localToUtc(r.planDate, Math.round(s.startMin) + s.durationMin) / 1000),
      timezone: PLAN_TZ,
      title: `#${s.seq} ${s.label}`.slice(0, 100),
      isPublished: PUBLISH,
      assignedUserIds: [r.tech.connecteamUserId],
      locationData: { isReferencedToJob: false, gps: { address: String(s.address || '').slice(0, 250), latitude: s.lat, longitude: s.lng } },
      notes: [{ html: notes.join('') }],
    };
    if (JOB_ID) shift.jobId = JOB_ID;
    return shift;
  });
  out.push({
    json: {
      kind: 'connecteam_request', ...base,
      delivery: connecteamDelivery,
      route: connecteamDelivery === 'live' ? 'connecteam_live' : 'simulate',
      request: { schedulerId: SCHEDULER_ID || 'YOUR_CONNECTEAM_SCHEDULER_ID', notifyUsers: PUBLISH, body: shifts },
    },
  });
}

// ── Slack plan summary ────────────────────────────────────────────────
const t = summary.totals;
const icon = summary.severity === 'critical' ? '🔴' : summary.severity === 'warning' ? '🟠' : '🟢';
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: `${icon} Route plan · ${summary.planDate}`, emoji: true } },
];
if (summary.severity === 'critical' && MENTION) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `${MENTION} dispatch needs attention` } });
blocks.push({
  type: 'section',
  fields: [
    { type: 'mrkdwn', text: `*Visits assigned*\n${t.assigned} of ${t.plannable} plannable (${t.visits} total)` },
    { type: 'mrkdwn', text: `*Technicians*\n${t.techniciansUsed} of ${t.techniciansAvailable} used` },
    { type: 'mrkdwn', text: `*Total drive*\n${Math.floor(t.driveMin / 60)} h ${t.driveMin % 60} min · ${t.distanceKm} km` },
    { type: 'mrkdwn', text: `*vs. naive order*\n${t.savingsPct}% less driving (${t.baselineDriveMin} → ${t.driveMin} min)` },
  ],
});
blocks.push({ type: 'divider' });
const ACTION = { create: connecteamDelivery === 'live' ? '📲 sent to Connecteam' : `📲 Connecteam (${connecteamDelivery})`, unchanged: '✔︎ already dispatched, unchanged', changed_after_dispatch: '⚠️ changed after dispatch: update Connecteam', slack_only: '💬 Slack only (no Connecteam user)', no_stops: '— no stops' };
for (const r of routes) {
  if (!r.stops.length) continue;
  const lines = r.stops.slice(0, 10).map((s) => `${s.seq}. \`${s.start}\` <${recordLink(s.objectType, s.recordId)}|${esc(s.label)}> · ${esc(s.city || '')}${s.priority === 'high' ? ' · *high*' : ''}${s.lateRisk ? ' · ⏱️ tight' : ''}${s.territoryMismatch ? ' · ↔︎ out of territory' : ''}`);
  if (r.stops.length > 10) lines.push(`…and ${r.stops.length - 10} more`);
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: `*${esc(r.tech.name)}* · ${r.totals.stops} stop${r.totals.stops === 1 ? '' : 's'} · ${r.totals.departAt}–${r.totals.finishAt} · ${r.totals.driveMin} min drive · ${r.totals.utilisationPct}% utilised\n_${ACTION[r.dispatchAction] || r.dispatchAction}_\n${lines.join('\n')}`.slice(0, 2900) },
  });
}
if (summary.unassigned.length) {
  const lines = summary.unassigned.slice(0, 12).map((u) => `• <${recordLink(u.objectType, u.recordId)}|${esc(u.label)}>${u.priority === 'high' ? ' *(high)*' : ''}: ${esc(REASON[u.reason] || u.reason)}${u.detail ? ` _(${esc(u.detail)})_` : ''}`);
  if (summary.unassigned.length > 12) lines.push(`…and ${summary.unassigned.length - 12} more`);
  blocks.push({ type: 'divider' });
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*Unassigned visits (${summary.unassigned.length})*\n${lines.join('\n')}`.slice(0, 2900) } });
}
const shownAlerts = summary.alerts.filter((a) => a.severity !== 'info' || summary.alerts.length < 6);
if (shownAlerts.length) {
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: shownAlerts.slice(0, 8).map((a) => `${a.severity === 'critical' ? '🔴' : a.severity === 'warning' ? '🟠' : 'ℹ️'} ${esc(a.message)}`).join('\n').slice(0, 2900) }] });
}
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `Run \`${esc(run.runId)}\` · ${esc(run.trigger)} · mode ${esc(run.mode)} · ${esc(summary.clusters.length)} clusters · travel legs: ${esc(summary.matrix.legsReturned)} Mapsly, ${esc(summary.matrix.estimatedLegsUsed)} estimated · n8n-hubspot-mapsly-territory-route-optimizer` }] });

out.push({
  json: {
    kind: 'slack_summary', run, planDate: summary.planDate, severity: summary.severity, totals: t, alerts: summary.alerts,
    unassignedCount: summary.unassigned.length, unassignedReasons: summary.unassigned.map((u) => u.reason), optimizer: summary.optimizer, matrix: summary.matrix, geocode: summary.geocode,
    delivery: slackDelivery, route: slackDelivery === 'live' ? 'slack_live' : 'simulate',
    slackMessage: { text: `Route plan ${summary.planDate}: ${t.assigned}/${t.plannable} visits assigned, ${t.unassigned} unassigned, ${t.driveMin} min total drive.`, blocks: blocks.slice(0, 50) },
  },
});

return out;

// ─────────────────────────────────────────────────────────────────────
// Node: Record Connecteam Result             Mode: Run Once for Each Item
// The create call is never retried automatically (a retry after a timeout
// could create duplicate shifts). Success stores the shift IDs and route
// fingerprint, so a re-plan doesn't dispatch the same route twice.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);
const KNOWN_SECRETS = ['HUBSPOT_ACCESS_TOKEN', 'MAPSLY_API_KEY', 'MAPSLY_GEO_ENDPOINT_URL', 'MAPSLY_MATRIX_ENDPOINT_URL', 'CONNECTEAM_API_TOKEN', 'SLACK_WEBHOOK_URL', 'WEBHOOK_SHARED_SECRET']
  .map((k) => env(k, '')).filter((v) => v.length >= 8);
const SECRET_KEY = /(authorization|token|secret|password|passwd|api[-_]?key|cookie|signature|webhook[-_]?url|endpoint[-_]?url)/i;
const redactString = (input) => {
  let s = String(input ?? '');
  for (const secret of KNOWN_SECRETS) s = s.split(secret).join('[REDACTED]');
  return s
    .replace(/Bearer\s+[A-Za-z0-9\-._~+\/]+=*/gi, 'Bearer [REDACTED]')
    .replace(/\bpat-[a-z0-9]{2,6}-[A-Za-z0-9-]{8,}\b/gi, '[REDACTED_HUBSPOT_TOKEN]')
    .replace(/https:\/\/hooks\.slack\.com\/[^\s"']+/gi, '[REDACTED_SLACK_WEBHOOK]')
    .replace(/https?:\/\/[^\s"']*mapsly\.com[^\s"']*/gi, '[REDACTED_MAPSLY_URL]')
    .replace(/\bxox[abposr]-[A-Za-z0-9-]+/g, '[REDACTED_SLACK_TOKEN]')
    .replace(/([?&](?:hapikey|api_key|apikey|key|token|secret|signature|sig)=)[^&\s"']+/gi, '$1[REDACTED]')
    .replace(/\b([A-Za-z0-9._%+-])[A-Za-z0-9._%+-]*@([A-Za-z0-9.-]+\.[A-Za-z]{2,})\b/g, '$1***@$2')
    .slice(0, 1000);
};
const redact = (value, depth = 0) => {
  if (depth > 7) return '[TRUNCATED]';
  if (value === null || value === undefined) return value ?? null;
  if (typeof value === 'string') return redactString(value);
  if (Array.isArray(value)) return value.slice(0, 60).map((v) => redact(v, depth + 1));
  if (typeof value === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(value)) out[k] = SECRET_KEY.test(k) ? '[REDACTED]' : redact(v, depth + 1);
    return out;
  }
  return value;
};

const ctx = $('Route Dispatch').item.json;
const res = $json || {};
const status = Number(res.statusCode || 0);
const shifts = res.body && res.body.data && Array.isArray(res.body.data.shifts) ? res.body.data.shifts : [];
const ok = status >= 200 && status < 300 && shifts.length > 0;

if (ok) {
  try {
    const store = $getWorkflowStaticData('global');
    store.hsRouteOptimizer = store.hsRouteOptimizer || { version: 1, dispatched: {} };
    store.hsRouteOptimizer.dispatched[`${ctx.planDate}:${ctx.tech.techId}`] = { fingerprint: ctx.fingerprint, shiftIds: shifts.map((s) => String(s.id)), at: Date.now() };
    // keep the ledger small: drop plan dates older than 14 days
    const cutoff = new Date(Date.now() - 14 * 86400000).toISOString().slice(0, 10);
    for (const key of Object.keys(store.hsRouteOptimizer.dispatched)) if (key.slice(0, 10) < cutoff) delete store.hsRouteOptimizer.dispatched[key];
  } catch (error) { /* ledger is best effort; the shifts exist either way */ }
}

const message = ok ? null : redactString((res.body && (res.body.message || res.body.detail || JSON.stringify(res.body).slice(0, 200))) || (res.error && (res.error.message || res.error)) || 'connecteam_request_failed').slice(0, 300);

return {
  json: {
    ...ctx,
    request: { schedulerId: ctx.request.schedulerId, shiftCount: ctx.request.body.length, notifyUsers: ctx.request.notifyUsers },
    dispatchResult: {
      channel: 'connecteam', simulated: false, mode: 'live', ok, statusCode: status || null,
      shiftIds: shifts.map((s) => String(s.id)), requestId: res.body && res.body.requestId ? String(res.body.requestId) : null,
      message, hint: status === 401 || status === 403 ? 'check CONNECTEAM_API_TOKEN' : status === 400 ? 'check that connecteamUserId is assigned to the scheduler' : null,
    },
  },
};

// ─────────────────────────────────────────────────────────────────────
// Node: Confirm Slack Delivery               Mode: Run Once for Each Item
