  rejectReason: item.kind === 'rejected' && item.run ? item.run.rejectReason : null,
  reason: item.reason || null,
  severity: item.severity || null,
  tech: item.tech ? { techId: item.tech.techId, connecteamUserId: item.tech.connecteamUserId } : null,
  dispatchAction: item.dispatchAction || null,
  routeTotals: item.kind !== 'slack_summary' && item.totals ? item.totals : null,
  planTotals: item.kind === 'slack_summary' && item.totals ? item.totals : null,
